/**	Instructions
	1. Set robHeading, robRow, robCol, targetRow, targetCol
		- Note targetRow and targetCol and 1index due to n-1
	2. Download and run.
	3. Press the left arm to begin
*/


const int screenHeight = 127;
const int screenWidth  = 177;
const int numOfRows = 4;
const int numOfCols = 6;

#define PATH 0
#define BLOCKED 1

int robHeading = 0; // 0=North, 1=East, 2=South, 3=West
int robRow = 3;	// y
int robCol = 1;	// x
int targetRow = 0;	// y
int targetCol = 3;	// x


typedef struct{
	int nWall;  // 0 = PATH, 1 = BLOCKED
	int eWall;
	int sWall;
	int wWall;

}cell;

cell maze[numOfRows][numOfCols];

// init. the outer borders coordinates of the maze
void buildOuterBorders(){
	for(int col=0; col<numOfCols; col++){
		maze[0][col].sWall = BLOCKED;
		maze[numOfRows-1][col].nWall = BLOCKED;
	}

	for(int row=0; row<numOfRows; row++){
		maze[row][0].wWall = BLOCKED;
		maze[row][numOfCols-1].eWall = BLOCKED;
	}
}

// Builds a sample maze in memory
void sampleMazeBuilder(){
		maze[0][0].nWall = maze[1][0].sWall = BLOCKED;
		maze[2][0].nWall = maze[3][0].sWall = BLOCKED;

		maze[0][1].nWall = maze[1][1].sWall = BLOCKED;
		maze[1][1].nWall = maze[2][1].sWall = BLOCKED;
		maze[2][1].nWall = maze[3][1].sWall = BLOCKED;
		maze[2][1].eWall = maze[2][2].wWall = BLOCKED;

		maze[0][2].eWall = maze[0][3].wWall = BLOCKED;
		maze[2][2].eWall = maze[2][3].wWall = BLOCKED;

		maze[0][3].nWall = maze[1][3].sWall = BLOCKED;
		maze[1][3].nWall = maze[2][3].sWall = BLOCKED;
		maze[2][3].nWall = maze[3][3].sWall = BLOCKED;

		maze[3][3].eWall = maze[3][4].wWall = BLOCKED;
		maze[0][4].nWall = maze[1][4].sWall = BLOCKED;
		maze[1][4].eWall = maze[1][5].wWall = BLOCKED;

		maze[2][5].nWall = maze[3][5].sWall = BLOCKED;
}

//=====================================================================
void gridDraw(){
	int XStart=0;
	int YStart=0;
	int XEnd  =0;
	int YEnd  =0;
	for(int i=0;i<numOfRows;i++){
		for(int j=0;j<numOfCols;j++){
			if(maze[i][j].nWall==BLOCKED){
					XStart= j   *screenWidth/numOfCols;
					YStart=(i+1)*screenHeight/numOfRows;
					XEnd  =(j+1)*screenWidth/numOfCols;
					YEnd  =(i+1)*screenHeight/numOfRows;
					drawLine(XStart,YStart,XEnd,YEnd);
			}
			if (maze[i][j].eWall==BLOCKED){
					XStart=(j+1)*screenWidth/numOfCols;
					YStart=(i)*screenHeight/numOfRows;
					XEnd  =(j+1)*screenWidth/numOfCols;
					YEnd  =(i+1)*screenHeight/numOfRows;
					drawLine(XStart,YStart,XEnd,YEnd);
			}
			if (maze[i][j].wWall==BLOCKED){
					XStart= j   *screenWidth/numOfCols;
					YStart=(i)*screenHeight/numOfRows;
					XEnd  =(j)*screenWidth/numOfCols;
					YEnd  =(i+1)*screenHeight/numOfRows;
					drawLine(XStart,YStart,XEnd,YEnd);
			}
			if(maze[i][j].sWall==BLOCKED){
				XStart= j   *screenWidth/numOfCols;
				YStart=(i)*screenHeight/numOfRows;
				XEnd  =(j+1)*screenWidth/numOfCols;
				YEnd  =(i)*screenHeight/numOfRows;
				drawLine(XStart,YStart,XEnd,YEnd);
			}
		}
	}
}

// Display the current arrangement of the maze on the screen
void robDraw(){
	eraseDisplay();
	gridDraw();
	switch(robHeading){
		case 0: displayStringAt(((robCol*2)+1)*screenWidth/12,((robRow*2)+1)* screenHeight/8, "^"); break;
		case 1: displayStringAt(((robCol*2)+1)*screenWidth/12,((robRow*2)+1)* screenHeight/8, ">"); break;
		case 2: displayStringAt(((robCol*2)+1)*screenWidth/12,((robRow*2)+1)* screenHeight/8, "v"); break;
		case 3: displayStringAt(((robCol*2)+1)*screenWidth/12,((robRow*2)+1)* screenHeight/8, "<"); break;
		default: break;
	}
	sleep(200);
}

// Reset Both Motor Encoders
void resetEncoders() {
	resetMotorEncoder(leftMotor);
	resetMotorEncoder(rightMotor);
}

// Set Motor Speeds of Motors
void setMotors(int lSpeed, int rSpeed) {
	resetEncoders();
	setMotorSpeed(leftMotor, lSpeed);
	setMotorSpeed(rightMotor, rSpeed);
}

// Turn robot to the right, update the robot direction, update the screen
void turnRight(){
	resetEncoders();
	setMotors(25,-25);
	while (getMotorEncoder(leftMotor) < 580) {}
	setMotors(0,0);
	switch(robHeading){
		case 0: robHeading = 1; break;
		case 1: robHeading = 2; break;
		case 2: robHeading = 3; break;
		case 3: robHeading = 0; break;
		default: break;
	}
	robDraw();
}

// Turn robot to the left, update the robot direction, update the screen
void turnLeft(){
	resetEncoders();
	setMotors(-25,25);
	while (getMotorEncoder(rightMotor) < 580) {}
	setMotors(0,0);
	switch(robHeading){
		case 0: robHeading = 3; break;
		case 1: robHeading = 0; break;
		case 2: robHeading = 1; break;
		case 3: robHeading = 2; break;
		default: break;
	}
	robDraw();
}

// Robot go forward one step, update the robot direction, update the screen
void goFwd(){
		resetEncoders();
		setMotors(50,50);
		while (getMotorEncoder(leftMotor) < 1450) {}
		setMotors(0,0);
		switch(robHeading){
			case 0: robRow++; break;
			case 1: robCol++; break;
			case 2: robRow--; break;
			case 3: robCol--; break;
			default: break;
		}
		robDraw();
}

// return a 0 for door, 1 for wall
int checkWall(){
	int l = getUSDistance(sonarSensor);
	clearSounds();
	if (l < 12) {
			playSound(2);
			int x = robRow;
			int y = robCol;
			int dir = robHeading;
		if (dir == 0) {
			maze[x][y].nWall =  BLOCKED;
			if (x < 3) {
				maze[x+1][y].sWall = BLOCKED;
			}
		}
			else if (dir == 1) {
				maze[x][y].eWall = BLOCKED;
				if (y < 5) {
				maze[x][y+1].wWall = BLOCKED;
			}
		}
		else if (dir == 2) {
			maze[x][y].sWall =  BLOCKED;
			if (x > 0) {
				maze[x-1][y].nWall = BLOCKED;
			}
		}
		else {
			maze[x][y].wWall =  BLOCKED;
			if (y > 0) {
				maze[x][y-1].eWall = BLOCKED;
			}
		}
		return BLOCKED;
	}
	switch(robHeading){
		case 0:
			return maze[robRow][robCol].nWall;
			break;
		case 1:
			return maze[robRow][robCol].eWall;
			break;
		case 2:
			return maze[robRow][robCol].sWall;
			break;
		case 3:
			return maze[robRow][robCol].wWall;
			break;
		default: break;
	}
	return -1;
}

int robotPath[100];
int stack[100];
int peek() {
	for (int i = 0 ; i < 100-1; ++i) {
		if (stack[i] != -1 && stack[i+1] == -1) {
			return stack[i];
		}
	}
	return -1;
}

//Add to the front of the array
void push(int x) {
	for (int i = 0 ; i < 100; ++i) {
		if (stack[i] == -1) {
			stack[i] = x;
			return;
		}
	}
}

//A
void pop() {
	for (int i = 0 ; i < 100-1; ++i) {
		if (stack[i+1] == -1) {
			stack[i] = -1;
			return;
		}
	}
}
bool isEmpty() {
	return stack[0] == -1;
}

// Reverse directions l <-> r and up <-> down
int mp(int dir) {
	if (dir == 0) {return 2;}
	else if (dir == 2) {return 0;}
	else if (dir == 1) {return 3;}
	else if (dir == 3) {return 1;}
	return -1;
}


// Bump into the wall to readjust position
void bumpAdjust() {
	resetEncoders();
	setMotors(60, 60);
	//while (getMotorEncoder(leftMotor) < 550) {}
	while(getTouchValue(leftArm) == 0 || getTouchValue(rightArm) == 0) {}
	setMotors(0,0);
	resetEncoders();
	setMotors(-25,-25);
	while (getMotorEncoder(rightMotor) > -350) {}
	setMotors(0,0);
}

task main(){
	//0. Push to start
	while(getTouchValue(leftArm) == 0) {}

buildOuterBorders();
gridDraw();
for (int i = 0; i < 100; ++i) {
	robotPath[i] = -1;
	stack[i] = -1;
}

// 1.  Head to the target cell using right-wall algorithm (see flowchart)
int idx = 0;
	while((robRow != targetRow)||(robCol != targetCol)){
			turnRight();
			while(checkWall()==1){
				bumpAdjust();
				turnLeft();
				sleep(100);
			}
			robotPath[idx] = robHeading;
			idx++;
			goFwd();
	}

	int n = idx;
	displayCenteredBigTextLine(3,"SOLVED !");
	sleep(2000);
	gridDraw();
	sleep(2000);

	push(robotPath[0]);
	//2. Simplify the path -> shortest path
	for (int i = 1; i < n; ++i) {
		if (!isEmpty() && mp(robotPath[i]) == peek()) { //remove matching pairs
			pop();
		}
		else {
			push(robotPath[i]);
		}
	}

	// 3. Head back using the shortest path
	for (int i = 0; i < 100; ++i) { // robotPath will be used for the final path (since stack path is reversed)
	robotPath[i] = -1;
}
int i = 0;
n = 0;
while (!isEmpty()) { // move simplified path from stack to path
	robotPath[i] = peek();
	pop();
	++i;
	++n;
}
for (int i = 0; i < n; ++i) { // for each path direction, reverse (to head back in opposite direction)
	robotPath[i] = mp(robotPath[i]);
	while(robHeading != robotPath[i]) {
		turnRight();
	}
	goFwd();
}

//Finish!
	while(true){
			displayCenteredBigTextLine(3,"RETURNED !");
			sleep(2000);
			gridDraw();
			sleep(2000);
	}
}
